@* Interactive island for the sidebar — lets the user cycle through themes. *@
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<div class="nav-item px-3">
    <button class="btn btn-sm btn-outline-light w-100" @onclick="CycleTheme"
            style="border-color: @ThemeSvc.AccentColor;">
        @icon @ThemeSvc.Theme mode
    </button>
</div>

@code {
    private string icon => ThemeSvc.Theme switch
    {
        Services.ThemeMode.Dark   => "🌙",
        Services.ThemeMode.Light  => "☀️",
        _                         => "💻"
    };

    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            Services.ThemeMode.Light  => Services.ThemeMode.Dark,
            Services.ThemeMode.Dark   => Services.ThemeMode.System,
            _                         => Services.ThemeMode.Light
        };
    }

    protected override void OnInitialized() => ThemeSvc.OnChange += StateHasChanged;
    public void Dispose()                   => ThemeSvc.OnChange -= StateHasChanged;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px; border-color: @ThemeSvc.AccentColor;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
            {
                var active = ThemeSvc.Theme == mode;
                <button class="btn @(active ? "btn-primary" : "btn-outline-primary")"
                        style="@(active ? $"background-color:{ThemeSvc.AccentColor};border-color:{ThemeSvc.AccentColor}" : "")"
                        @onclick="() => ThemeSvc.Theme = mode">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnColorChanged" />
            <span class="badge rounded-pill"
                  style="background-color: @ThemeSvc.AccentColor; color: white;">
                @ThemeSvc.AccentColor
            </span>
        </div>

        <h5 class="card-title">Preview</h5>
        <p>
            Current theme: <strong>@ThemeSvc.Theme</strong><br />
            Accent color: <strong>@ThemeSvc.AccentColor</strong>
        </p>
    </div>
</div>

@code {
    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    protected override void OnInitialized() => ThemeSvc.OnChange += StateHasChanged;
    public void Dispose()                   => ThemeSvc.OnChange -= StateHasChanged;
}

